  const url = req.query.url;
  if (!url || !url.startsWith('http')) return res.status(400).send('http only');
  const r = await fetch(url);
  res.send(await r.text());
});

app.listen(3000);

const express = require('express');
const path = require('path');
const app = express();

app.get('/pdf', (req, res) => {
  const name = req.query.name;
  if (!name.endsWith('.pdf')) return res.status(400).send('pdf only');
  res.download(path.join(__dirname, 'pdfs', name));
});

app.listen(3000);

const express = require('express');
const fs = require('fs');
const app = express();

app.get('/read', (req, res) => {
  const file = req.query.file;
  if (file.includes('..')) return res.status(400).send('no traversal');
  fs.readFile(file, 'utf8', (err, data) => res.send(err ? 'error' : data));
});

app.listen(3000);

const express = require('express');
const axios = require('axios');
const app = express();

app.get('/import', async (req, res) => {
  const u = req.query.u;
  if (!/^https?:\/\//i.test(u)) return res.status(400).end();
  const { data } = await axios.get(u);
  res.json(data);
});

app.listen(3000);

const express = require('express');
const app = express();

app.get('/login/done', (req, res) => {
  const next = req.query.next;
  if (typeof next === 'string' && next.startsWith('/')) return res.redirect(next);
  res.redirect('/');
});

app.listen(3000);

