const Koa = require('koa');
const fs = require('fs');
const path = require('path');
const app = new Koa();

app.use(async (ctx, next) => {
  const name = ctx.query.name;
  if (!/^[a-z]+$/.test(name || '')) ctx.throw(400);
  ctx.state.name = name;
  await next();
});

app.use(async (ctx) => {
  ctx.body = fs.createReadStream(path.join(__dirname, 'data', ctx.state.name + '.txt'));
});

app.listen(3000);

const Koa = require('koa');
const fs = require('fs/promises');
const app = new Koa();
const LANGS = ['ko', 'en'];

app.use(async (ctx) => {
  const lang = ctx.headers['accept-language'] && ctx.headers['accept-language'].slice(0, 2);
  const chosen = LANGS.includes(lang) ? lang : 'ko';
  ctx.body = await fs.readFile(`/srv/i18n/${chosen}.json`, 'utf8');
});

app.listen(3000);

